// Authored QI-Games sprites exposed as Image objects for the 3D world page.
// Sources (prefer local-sovereign generation when present):
//   - assets/<role>.png  generated by scripts/gen_sprites.py (white+indigo,
//     per-role gem) -- the sovereign fallback when ChatGPT art is absent.
//   - ChatGPT-authored art (fairy/berry/crystal/spellbook/tile) normalized by
//     scripts/normalize.py remains available; gen_sprites adds role variants
//     + flower so every society role has its own texture.
window.QIG_SPRITES = {};
const names = ["forager","trader","builder","scout","curator","you",
               "fairy","berry","crystal","spellbook","tile","flower"];
for (const n of names) {
  window.QIG_SPRITES[n] = new Image();
  window.QIG_SPRITES[n].src = "assets/" + n + ".png";
}

// Map a society role to its dedicated texture (fallback to fairy for "you").
window.QIG_ROLE_SPRITE = {
  forager:  "forager",  trader: "trader",   builder: "builder",
  scout:    "scout",    curator: "curator", you:     "you",
};
